local ScytheSmith = {}
local PRODUCTS = {
    simple_iron_scythe = { name = "Preprosta železna kosa", ironCost = 2, woodCost = 2, time = 4, cost = 70, food = 14, happiness = 1, description = "Preprosta železna kosa za košnjo." },
    steel_blade_scythe = { name = "Jeklenorezna kosa", ironCost = 2, steelCost = 1, woodCost = 2, time = 6, cost = 180, food = 22, happiness = 1, prestige = 2, description = "Jeklenorezna kosa za trgovce." },
    silver_trimmed_scythe = { name = "Srebrnoobrobljena kosa", ironCost = 2, silverCost = 1, steelCost = 1, woodCost = 2, time = 9, cost = 440, food = 35, happiness = 2, prestige = 6, description = "Srebrnoobrobljena kosa za plemiče." },
    gold_trimmed_scythe = { name = "Zlatookrasna kosa", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 2, time = 13, cost = 1000, food = 48, happiness = 3, prestige = 14, description = "Zlatookrasna kosa za visoke plemiče." },
    jewel_set_scythe = { name = "Draguljasta kosa", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 2, jewelCost = 1, time = 17, cost = 2200, food = 62, happiness = 5, prestige = 27, description = "Kosa z draguljem za visoko plemstvo." },
    royal_grand_scythe = { name = "Kraljevski veliki kosa", ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 4800, food = 82, happiness = 12, prestige = 58, description = "Velika kraljevska kosa z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    scythe_workshop = { name = "Kosarska delavnica", cost = { gold = 250, wood = 140, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 900, wood = 300, stone = 240, silver = 6, steel = 4 }, upkeep = 21, qualityBonus = 18 },
    master_scythe_atelier = { name = "Mojstrski kosarski atelje", cost = { gold = 2600, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 60, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 11000, wood = 580, stone = 760, gold = 70, jewel = 16 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
ScytheSmith.ironStock = 14; ScytheSmith.steelStock = 10; ScytheSmith.woodStock = 12; ScytheSmith.silverStock = 6; ScytheSmith.goldStock = 6; ScytheSmith.jewelStock = 4; ScytheSmith.pearlStock = 4
ScytheSmith.productStock = {}; ScytheSmith.buildings = {}; ScytheSmith.maker = nil; ScytheSmith.activeMaking = {}; ScytheSmith.totalProducts = 0; ScytheSmith.dayTimer = 0
function ScytheSmith.init() ScytheSmith.ironStock=14; ScytheSmith.steelStock=10; ScytheSmith.woodStock=12; ScytheSmith.silverStock=6; ScytheSmith.goldStock=6; ScytheSmith.jewelStock=4; ScytheSmith.pearlStock=4; ScytheSmith.productStock={}; ScytheSmith.buildings={}; ScytheSmith.maker=nil; ScytheSmith.activeMaking={}; ScytheSmith.totalProducts=0; ScytheSmith.dayTimer=0; print("[ScytheSmith] Royal Scythe Smith System initialized (6 products, 4 buildings)") end
function ScytheSmith.hireMaker(n,s) s=s or math.random(55,90); local c=530+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ScytheSmith.maker={name=n or ("Kosar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kosar najet: %s (spretnost: %d)",ScytheSmith.maker.name,s),"success") end; return true end
function ScytheSmith.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ScytheSmith.build(id) local ok,e=ScytheSmith.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ScytheSmith.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ScytheSmith.getQualityBonus() local b=0; for _,bd in ipairs(ScytheSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ScytheSmith.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ScytheSmith.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and ScytheSmith.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and ScytheSmith.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and ScytheSmith.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ScytheSmith.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ScytheSmith.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ScytheSmith.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ScytheSmith.buildings==0 then return false,"Potrebna kosarska delavnica" end; if not ScytheSmith.maker then return false,"Potreben kosar" end; return true end
function ScytheSmith.make(pt,qty) qty=qty or 1; local ok,e=ScytheSmith.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ScytheSmith.ironStock=ScytheSmith.ironStock-d.ironCost*qty end; if d.steelCost then ScytheSmith.steelStock=ScytheSmith.steelStock-d.steelCost*qty end; if d.woodCost then ScytheSmith.woodStock=ScytheSmith.woodStock-d.woodCost*qty end; if d.silverCost then ScytheSmith.silverStock=ScytheSmith.silverStock-d.silverCost*qty end; if d.goldCost then ScytheSmith.goldStock=ScytheSmith.goldStock-d.goldCost*qty end; if d.jewelCost then ScytheSmith.jewelStock=ScytheSmith.jewelStock-d.jewelCost*qty end; if d.pearlCost then ScytheSmith.pearlStock=ScytheSmith.pearlStock-d.pearlCost*qty end; local t=d.time; if ScytheSmith.maker then t=math.max(1,t-math.floor(ScytheSmith.maker.skill/13)) end; table.insert(ScytheSmith.activeMaking,{id="scythe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ScytheSmith.completeMaking(m) local q=1.0+(ScytheSmith.getQualityBonus()/100); if ScytheSmith.maker then q=q+(ScytheSmith.maker.skill/140) end; q=math.min(2.5,q); ScytheSmith.productStock[m.productType]=(ScytheSmith.productStock[m.productType] or 0)+m.quantity; ScytheSmith.totalProducts=ScytheSmith.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ScytheSmith.maker then ScytheSmith.maker.itemsMade=ScytheSmith.maker.itemsMade+m.quantity; if math.random()<0.25 then ScytheSmith.maker.skill=math.min(100,ScytheSmith.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kosa izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"scythe.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function ScytheSmith.update(dt) if not _G.state then return end; ScytheSmith.dayTimer=ScytheSmith.dayTimer+dt; if ScytheSmith.dayTimer>=30 then ScytheSmith.dayTimer=0; for i=#ScytheSmith.activeMaking,1,-1 do local m=ScytheSmith.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ScytheSmith.completeMaking(m); table.remove(ScytheSmith.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ScytheSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ScytheSmith.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ScytheSmith.getStats() return {ironStock=ScytheSmith.ironStock,steelStock=ScytheSmith.steelStock,woodStock=ScytheSmith.woodStock,silverStock=ScytheSmith.silverStock,goldStock=ScytheSmith.goldStock,jewelStock=ScytheSmith.jewelStock,pearlStock=ScytheSmith.pearlStock,productStock=ScytheSmith.productStock,numBuildings=#ScytheSmith.buildings,hasMaker=ScytheSmith.maker~=nil,makerName=ScytheSmith.maker and ScytheSmith.maker.name or "—",makerSkill=ScytheSmith.maker and ScytheSmith.maker.skill or 0,activeMaking=#ScytheSmith.activeMaking,totalProducts=ScytheSmith.totalProducts} end
return ScytheSmith
